import{_ as l,H as p,o as A,c as g,aN as s,q as e,s as E,a as t,l as r,aT as o,j as n}from"./chunks/framework.D31DlcCL.js";const T=JSON.parse('{"title":"AI大模型修仙传（七）：LangChain初探——给大模型装上“四肢”和“工具箱”","description":"大模型虽然聪明，但就像个“缸中之脑”。今天我们来聊聊LangChain，看看它是如何给AI装上四肢、插上记忆的翅膀，让大模型从“纸上谈兵”变成“全能打工人”的！","frontmatter":{"title":"AI大模型修仙传（七）：LangChain初探——给大模型装上“四肢”和“工具箱”","date":"2026-04-01T00:00:00.000Z","categories":["AI"],"tags":["LangChain","LLM","大模型","Agent","提示词工程"],"description":"大模型虽然聪明，但就像个“缸中之脑”。今天我们来聊聊LangChain，看看它是如何给AI装上四肢、插上记忆的翅膀，让大模型从“纸上谈兵”变成“全能打工人”的！"},"headers":[],"relativePath":"posts/ai-series-7-langchain-basics.md","filePath":"posts/ai-series-7-langchain-basics.md","lastUpdated":null}'),B={name:"posts/ai-series-7-langchain-basics.md"};function h(C,a,d,m,u,L){const i=p("Mermaid");return A(),g("div",null,[a[3]||(a[3]=s('<h1 id="ai大模型修仙传-七-langchain初探——给大模型装上-四肢-和-工具箱" tabindex="-1">AI大模型修仙传（七）：LangChain初探——给大模型装上“四肢”和“工具箱” <a class="header-anchor" href="#ai大模型修仙传-七-langchain初探——给大模型装上-四肢-和-工具箱" aria-label="Permalink to &quot;AI大模型修仙传（七）：LangChain初探——给大模型装上“四肢”和“工具箱”&quot;">​</a></h1><blockquote><p><strong>💡 博主导读</strong>：LangChain不仅是工具，更是一种重塑AI应用开发的全新架构思想。如果你想在AI时代开发出真正落地的商业级应用，这套“外骨骼”你必须熟练掌握！</p></blockquote><h1 id="ai大模型修仙传-七-langchain初探——给大模型装上-四肢-和-工具箱-1" tabindex="-1">AI大模型修仙传（七）：LangChain初探——给大模型装上“四肢”和“工具箱” <a class="header-anchor" href="#ai大模型修仙传-七-langchain初探——给大模型装上-四肢-和-工具箱-1" aria-label="Permalink to &quot;AI大模型修仙传（七）：LangChain初探——给大模型装上“四肢”和“工具箱”&quot;">​</a></h1><p>各位道友，欢迎回到《AI大模型修仙传》。</p><p>在前面的章节里，我们见证了各大AI模型如何在“藏经阁”中闭关苦读，汲取了人类几千年的知识精华，最终练就了通天彻地的“自然语言生成”神功。</p><p>你一定体验过这种震撼：你问它量子力学，它对答如流；你让它写首七律，它文采飞扬。</p><p>但是，当你真的想请这位“大能”出山，帮你在现实世界里搬砖时，你会发现一个让人哭笑不得的真相——</p><p><strong>这位拥有顶级智慧的大能，竟然是个“高位截瘫”。</strong></p><p>你让他去查一下今天下午的航班，他两手一摊：“本座的记忆只停留在训练截止的昨天。” 你让他算一个极其复杂的开根号，他一本正经地给你胡编乱造了一个答案。 你让他把一份100页的PDF总结一下发给老板，他直接宕机：“字数太多，本座看不过来。”</p><p>发现问题了吗？<strong>大模型本质上是一个“缸中之脑”</strong>。它极其聪明，但它没有手脚去接触外部世界，没有工具去执行具体任务，也没有长期记忆来记住你们上个月的谈话。</p><p>直到 <strong>LangChain</strong> 横空出世。</p><p>如果说大模型是修仙界最强的大脑，那么 LangChain 就是为这个大脑量身定制的“外骨骼机甲”和“法宝套装”。今天，我们就来拆解一下这套神器，看看它是如何让大模型长出四肢的。</p><hr><h2 id="一、-prompts-提示词-修仙界的-标准化符箓" tabindex="-1">一、 Prompts（提示词）：修仙界的“标准化符箓” <a class="header-anchor" href="#一、-prompts-提示词-修仙界的-标准化符箓" aria-label="Permalink to &quot;一、 Prompts（提示词）：修仙界的“标准化符箓”&quot;">​</a></h2>',14)),(A(),e(o,null,{default:E(()=>[r(i,{id:"mermaid-42",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20User%5B%E7%94%A8%E6%88%B7%E9%9A%8F%E6%84%8F%E8%BE%93%E5%85%A5%5D%20--%3E%20Template%5BPrompt%E6%A8%A1%E6%9D%BF%3A%20%E6%B3%A8%E5%85%A5%E4%B8%93%E5%AE%B6%E4%BA%BA%E8%AE%BE%2F%E6%A0%BC%E5%BC%8F%E8%A6%81%E6%B1%82%5D%0A%20%20%20%20Template%20--%3E%20LLM%5B%E5%A4%A7%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20LLM%20--%3E%20Output%5B%E6%A0%87%E5%87%86%E5%8C%96%2F%E4%B8%93%E4%B8%9A%E5%8C%96%E7%9A%84%E8%BE%93%E5%87%BA%5D%0A%20%20%20%20style%20Template%20fill%3A%23bbf%2Cstroke%3A%23333%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n("p",null,"大模型虽然听得懂人话，但有时候它的发挥极其不稳定。你让它写个总结，它今天给你写三句，明天给你写三万字。",-1)),a[5]||(a[5]=n("p",null,[t("在工程应用中，我们最怕的就是“不确定性”。这时候，LangChain 的第一个法宝 "),n("strong",null,"Prompts（提示词模板）"),t(" 就派上用场了。")],-1)),a[6]||(a[6]=n("p",null,"不要以为提示词就是你在对话框里随便敲的几句话。在 LangChain 中，提示词被做成了“标准化符箓”。",-1)),a[7]||(a[7]=n("p",null,"你可以定义一个极其严谨的模板： “你现在是一个拥有20年经验的资深架构师，请根据用户的输入：{user_input}，输出一份系统设计方案。要求：必须包含背景、架构图描述和核心API，语气要极其专业，且字数控制在500字以内。”",-1)),a[8]||(a[8]=n("p",null,"通过这种模板化的“画符”，你可以将用户的任何随意输入，瞬间转化为对大模型最精准的指令。这就像是给大模型的超强内力加上了一个定向发射器，指哪打哪。",-1)),a[9]||(a[9]=n("hr",null,null,-1)),a[10]||(a[10]=n("h2",{id:"二、-chains-链-从单打独斗到-阵法连招",tabindex:"-1"},[t("二、 Chains（链）：从单打独斗到“阵法连招” "),n("a",{class:"header-anchor",href:"#二、-chains-链-从单打独斗到-阵法连招","aria-label":'Permalink to "二、 Chains（链）：从单打独斗到“阵法连招”"'},"​")],-1)),(A(),e(o,null,{default:E(()=>[r(i,{id:"mermaid-62",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20Input%5B%E8%BE%93%E5%85%A5%E7%BD%91%E5%9D%80%5D%20--%3E%20Chain1%5B%E9%93%BE1%3A%20%E7%BD%91%E9%A1%B5%E6%8A%93%E5%8F%96%E4%B8%8E%E8%A7%A3%E6%9E%90%5D%0A%20%20%20%20Chain1%20--%3E%20Chain2%5B%E9%93%BE2%3A%20LLM%E6%8F%90%E5%8F%96%E6%A0%B8%E5%BF%83%E8%A7%82%E7%82%B9%5D%0A%20%20%20%20Chain2%20--%3E%20Chain3%5B%E9%93%BE3%3A%20LLM%E7%BF%BB%E8%AF%91%E4%B8%8E%E9%87%8D%E5%86%99%E6%8E%A8%E6%96%87%5D%0A%20%20%20%20Chain3%20--%3E%20Final%5B%E6%9C%80%E7%BB%88%E5%BE%AE%E4%BF%A1%E6%8E%A8%E6%96%87%5D%0A%20%20%20%20style%20Chain1%20fill%3A%23dfd%2Cstroke%3A%23333%0A%20%20%20%20style%20Chain2%20fill%3A%23dfd%2Cstroke%3A%23333%0A%20%20%20%20style%20Chain3%20fill%3A%23dfd%2Cstroke%3A%23333%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[11]||(a[11]=s('<p>真实世界里的业务逻辑，往往不是一问一答就能解决的。</p><p>假设你有一个需求：“先去网上抓取一篇最新的AI论文，然后提取核心观点，最后把这些观点翻译成中文，并写成一篇微信推文。”</p><p>如果让人来干，这需要四个步骤。如果只用原生大模型，你需要手动把上一步的输出复制下来，作为下一步的输入贴进去。这哪是人工智能，这叫人工智障。</p><p>LangChain 的核心精髓就在这个 <strong>Chain（链）</strong> 字上。它允许你把多个操作像“锁链”一样串联起来，形成一套丝滑的“阵法连招”。</p><p>第一环：信息获取链（去读论文）。 第二环：摘要生成链（提炼观点）。 第三环：翻译与重写链（生成推文）。</p><p>数据在这些链条中自动流转，上一个大模型的输出，无缝衔接成下一个大模型的输入。你只需要按下启动键，剩下的就是见证奇迹的时刻。</p><hr><h2 id="三、-memory-记忆-给大模型装上-海马体" tabindex="-1">三、 Memory（记忆）：给大模型装上“海马体” <a class="header-anchor" href="#三、-memory-记忆-给大模型装上-海马体" aria-label="Permalink to &quot;三、 Memory（记忆）：给大模型装上“海马体”&quot;">​</a></h2><p>用过 API 调用的开发者都知道，大模型是“没有状态”的。用修仙的话说，就是“斩断尘缘，活在当下”。</p><p>你跟它聊了半小时，只要下一次请求你不把之前的聊天记录原封不动地传给它，它就会把你忘得干干净净。但如果每次都把所有历史记录传过去，那高昂的 Token 费用（算力成本）会让你的钱包瞬间破产。</p><p>LangChain 的 <strong>Memory（记忆组件）</strong> 完美解决了这个痛点。它给大模型装上了一个智能的“海马体”。</p><p>它可以是“短期记忆”：只记住最近的5轮对话。 也可以是“摘要记忆”：LangChain 会在后台偷偷用另一个小模型，把你们之前聊过的废话浓缩成一句核心摘要，然后再喂给主模型。</p><p>有了 Memory，大模型终于不仅能懂你当下的需求，还能理解你的前因后果。它不再是一个失忆的机器，而是一个真正的专属助理。</p><hr><h2 id="四、-agents-代理-真正的-撒豆成兵-与-手脚" tabindex="-1">四、 Agents（代理）：真正的“撒豆成兵”与“手脚” <a class="header-anchor" href="#四、-agents-代理-真正的-撒豆成兵-与-手脚" aria-label="Permalink to &quot;四、 Agents（代理）：真正的“撒豆成兵”与“手脚”&quot;">​</a></h2>',15)),(A(),e(o,null,{default:E(()=>[r(i,{id:"mermaid-104",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Task%5B%E7%94%A8%E6%88%B7%E7%9B%AE%E6%A0%87%3A%20%E6%9F%A5%E8%82%A1%E4%BB%B7%E5%B9%B6%E8%AE%A1%E7%AE%97%E4%BA%BA%E6%B0%91%E5%B8%81%5D%20--%3E%20Agent((Agent%20%E5%A4%A7%E8%84%91))%0A%20%20%20%20Agent%20--%3E%7C%E6%80%9D%E8%80%83%3A%20%E9%9C%80%E8%A6%81%E6%9C%80%E6%96%B0%E6%95%B0%E6%8D%AE%7C%20Tool1%5B%E8%B0%83%E7%94%A8%20%E6%90%9C%E7%B4%A2%E5%BC%95%E6%93%8E%5D%0A%20%20%20%20Tool1%20--%3E%7C%E8%BF%94%E5%9B%9E%3A%20170%E7%BE%8E%E5%85%83%7C%20Agent%0A%20%20%20%20Agent%20--%3E%7C%E6%80%9D%E8%80%83%3A%20%E9%9C%80%E8%A6%81%E7%B2%BE%E7%A1%AE%E8%AE%A1%E7%AE%97%7C%20Tool2%5B%E8%B0%83%E7%94%A8%20%E8%AE%A1%E7%AE%97%E5%99%A8%5D%0A%20%20%20%20Tool2%20--%3E%7C%E8%BF%94%E5%9B%9E%3A%20122400%E5%85%83%7C%20Agent%0A%20%20%20%20Agent%20--%3E%7C%E5%BE%97%E5%87%BA%E7%BB%93%E8%AE%BA%7C%20Answer%5B%E6%9C%80%E7%BB%88%E5%9B%9E%E5%A4%8D%E7%94%A8%E6%88%B7%5D%0A%20%20%20%20style%20Agent%20fill%3A%23f9f%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:E(()=>[...a[2]||(a[2]=[t(" Loading... ",-1)])]),_:1})),a[12]||(a[12]=s('<p>如果说前面三个组件只是让大模型用起来更顺手，那么 <strong>Agents（代理）</strong> 则是 LangChain 真正让人头皮发麻、直呼内行的终极杀器！</p><p>什么是 Agent？简单来说，就是<strong>大模型不仅能思考，还能自己决定使用什么工具，自己采取行动。</strong></p><p>在这个阶段，你不再是给大模型下达具体的执行指令，而是给它一个“目标”，并扔给它一个“工具箱”（Tools）。</p><p>假设你给了它两个法宝：</p><ol><li><strong>搜索引擎工具</strong>（可以联网查资料）</li><li><strong>计算器工具</strong>（可以做精准的数学运算）</li></ol><p>然后你问它：“苹果公司昨天的收盘价是多少？如果我买 100 股，需要花多少人民币？（假设汇率是 7.2）”</p><p>接下来，你会看到 Agent 令人窒息的内部思考过程（ReAct 框架：Reason + Act）：</p><ul><li><strong>思考 1</strong>：用户需要苹果昨天的收盘价，我的大脑里没有最新数据，我必须使用【搜索引擎工具】。</li><li><strong>行动 1</strong>：调用搜索引擎 -&gt; 得到结果：170美元。</li><li><strong>思考 2</strong>：用户要买100股，并且要换算成人民币，我需要算 170 * 100 * 7.2。大模型做数学容易算错，我必须使用【计算器工具】。</li><li><strong>行动 2</strong>：调用计算器 -&gt; 得到结果：122400。</li><li><strong>思考 3</strong>：我已经得到了所有必要信息，可以回答用户了。</li><li><strong>最终输出</strong>：“苹果公司昨天的收盘价是170美元，购买100股折合人民币约122400元。”</li></ul><p>看到了吗？这就是 Agent！大模型不再是被动回答问题的文本生成器，它变成了一个拥有逻辑推理能力、能够自主调度外部工具的“智能体”。</p><p>给它数据库查询权限，它就能自己写 SQL 帮你查报表；给它发邮件的 API，它就能自己读完日程表后帮你给客户发邀约。</p><p><strong>大模型终于长出了手脚，能够直接改造物理世界了。</strong></p><hr><h2 id="结语-从-工具-到-大脑-的范式转移" tabindex="-1">结语：从“工具”到“大脑”的范式转移 <a class="header-anchor" href="#结语-从-工具-到-大脑-的范式转移" aria-label="Permalink to &quot;结语：从“工具”到“大脑”的范式转移&quot;">​</a></h2><p>LangChain 的爆火，绝不仅仅是因为它是一个好用的 Python/JS 库。它代表着一种全新的编程范式。</p><p>以前我们写代码，是用 if-else 来规定程序每一步该怎么走。 现在我们写代码，是用 LangChain 构建一个环境，提供一堆工具，然后把控制权交给大模型，对它说：“目标我已经定好了，过程你自己看着办。”</p><p>有了 LangChain，大模型才真正从“玩具”变成了“生产力工具”。</p><p>好了，今天的《大模型修仙传》就聊到这里。懂了概念只是第一步，下一期，我们将直接进入“炼器室”，手把手带你用几十行代码，撸出一个能帮你自动读长篇报告并总结汇报的专属 Agent 助理！</p><p>如果你觉得这篇文章对你有启发，别忘了点赞、转发、在看三连！你的支持就是博主持续爆肝更新的最大动力。我们下期见！</p>',18))])}const D=l(B,[["render",h]]);export{T as __pageData,D as default};
